SELECT
        REPLACE(CAST(EMISOR AS TEXT),'0144','0104') AS EMISOR,
        LPAD(CODIGO,6,'0') ||
        LPAD(REPLACE(CAST(CONVERSION AS TEXT),'.',''),18,'0') ||
        LPAD(REPLACE(CAST(C_CONVERSION AS TEXT),'.',''),18,'0') ||
        LPAD(REPLACE(CAST(TRANSFERENCIAS AS TEXT),'.',''),18,'0') ||
        LPAD(REPLACE(CAST(C_TRANSFERENCIAS AS TEXT),'.',''),18,'0') ||
        LPAD(REPLACE(CAST(RECONVERSION AS TEXT),'.',''),18,'0') ||
        LPAD(REPLACE(CAST(C_RECONVERSION AS TEXT),'.',''),18,'0') ||
        LPAD(REPLACE(CAST(OTROS AS TEXT),'.',''),18,'0') ||
        LPAD(REPLACE(CAST(C_OTROS AS TEXT),'.',''),18,'0') ||
        LPAD('0',6,'0') AS TRAMA
FROM DATA_FINAL
ORDER BY 1 DESC,CODIGO ASC
